+// Resolve a program URL against the current browser origin.
+//
+// Supports:
+//   - Absolute URLs: "https://example.com/app" (returned as-is)
+//   - Root-relative paths: "/codesmith" (origin + path)
+//   - Simple paths: "codesmith" (origin + "/" + path)
+function resolveProgramUrl(rawUrl) {
+  if (!rawUrl) return null;
+  const trimmed = String(rawUrl).trim();
+  if (!trimmed) return null;
+
+  // If this already looks like an absolute http(s) URL, use it as-is.
+  if (/^https?:\/\//i.test(trimmed)) {
+    return trimmed;
+  }
+
+  const origin = window.location.origin || '';
+
+  // "/codesmith" -> "https://host:port/codesmith"
+  if (trimmed.startsWith('/')) {
+    return origin + trimmed;
+  }
+
+  // "codesmith" -> "https://host:port/codesmith"
+  const base = origin.replace(/\/+$/, '');
+  const path = trimmed.replace(/^\/+/, '');
+  return `${base}/${path}`;
+}

